errors.New("not found")                      // static text
fmt.Errorf("user %d: not found", id)         // formatted, no wrapping
fmt.Errorf("load user: %w", err)             // formatted, WRAPS err

// a custom type, when callers need the details
type NotFoundError struct{ ID int }
func (e *NotFoundError) Error() string {
	return fmt.Sprintf("user %d not found", e.ID)
}

var nf *NotFoundError
if errors.As(err, &nf) {
	log.Printf("missing user %d", nf.ID)
}

// sentinel - the caller only needs the category
var ErrNotFound = errors.New("not found")

// typed - the caller needs the details
type ValidationError struct {
	Field string
	Value any
}

func (e *ValidationError) Error() string {
	return fmt.Sprintf("invalid %s: %v", e.Field, e.Value)
}

for {
	n, err := r.Read(buf)
	if n > 0 {
		process(buf[:n])   // use the bytes FIRST
	}
	if err == io.EOF {
		break              // normal end
	}
	if err != nil {
		return err         // a real failure
	}
}

